</code></pre> FastAPIFlask main.py<pre><code>from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
from models import ContactForm

from pydantic_schemaforms import html, render_form_html_async

ContactSchema = ContactForm.as_api_model()  # same fields and rules, no ui_* settings
app = FastAPI()


@app.get('/contact', response_class=HTMLResponse)
async def show_contact():
    return await render_form_html_async(ContactForm, submit_url='/contact')


@app.post('/contact', response_class=HTMLResponse)
async def submit_contact(request: Request):
    result = ContactForm.validate(await request.form(), submit_url='/contact')
    if not result.is_valid:
        return await result.render_with_errors_async()
    name = result.data['name']
    return html(t'&lt;p&gt;Thanks, {name}!&lt;/p&gt;')


@app.post('/api/contact', response_model=ContactSchema)
async def api_contact(contact: ContactSchema):
    return contact
</code></pre> <p><code>ContactForm.as_api_model()</code> returns a plain Pydantic model with the same fields and the same validation (<code>min_length</code>, <code>title</code>, <code>examples</code>, ...), but without the form settings such as <code>ui_element</code> and <code>ui_autofocus</code>. Use it as the request body or <code>response_model</code>, and FastAPI's OpenAPI docs show a clean schema, exactly as for a model written by hand. Create it once, at import time.</p> main.py<pre><code>from flask import Flask, request
from models import ContactForm

from pydantic_schemaforms import html, render_form_html

app = Flask(__name__)


@app.get('/contact')
def show_contact():
    return render_form_html(ContactForm, submit_url='/contact')


@app.post('/contact')
def submit_contact():
    result = ContactForm.validate(request.form, submit_url='/contact')
    if not result.is_valid:
        return result.render_with_errors()
    name = result.data['name']
    return html(t'&lt;p&gt;Thanks, {name}!&lt;/p&gt;')


@app.post('/api/contact')
def api_contact():
    result = ContactForm.validate(request.get_json(silent=True) or {})
    if not result.is_valid:
        return {'errors': result.errors}, 422
    return result.data
</code></pre> <p><code>validate()</code> takes a JSON body as well as a form. Give it the parsed JSON (a nested dict) and it returns the same <code>ValidationResult</code>, so the API route can answer with <code>result.errors</code>, nested like the data, and a 422 status.</p>

models.py<pre><code>from pydantic_schemaforms import Field, FormModel, FormValidator, PhoneRule


class SignupForm(FormModel):
    username: str = Field(title='Username', min_length=3)
    phone: str = Field('', title='Phone', ui_element='tel')
    age: int = Field(title='Age', ge=0)
    parental_consent: bool = Field(False, title='A parent agrees')


def minors_need_consent(data: dict) -&gt; tuple[bool, dict]:
    age = data.get('age')
    if age is not None and int(age) &lt; 18 and not data.get('parental_consent'):
        return False, {'parental_consent': 'A parent must agree for anyone under 18'}
    return True, {}


rules = FormValidator()
rules.field('phone').add_rule(PhoneRule())
rules.add_cross_field_rule(minors_need_consent)
</code></pre> FastAPIFlask main.py<pre><code>from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
from models import SignupForm, rules

from pydantic_schemaforms import html, render_form_html_async

app = FastAPI()


@app.get('/signup', response_class=HTMLResponse)
async def show_signup():
    return await render_form_html_async(SignupForm, submit_url='/signup')


@app.post('/signup', response_class=HTMLResponse)
async def submit_signup(request: Request):
    result = SignupForm.validate(await request.form(), submit_url='/signup')
    rules_ok, rule_errors = rules.validate(result.original_data)
    if not (result.is_valid and rules_ok):
        return await result.render_with_errors_async(errors={**rule_errors, **result.errors})
    username = result.data['username']
    return html(t'&lt;p&gt;Welcome, {username}!&lt;/p&gt;')
